SELECT l.*,
       p.dept_id AS dept_id,
       p.owner_id AS owner_id
FROM oa_budget_ledger l
         INNER JOIN oa_budget_plan p ON p.budget_id = l.budget_id AND p.deleted = '0'



            AND l.budget_id = #{query.budgetId}


            AND l.subject_code = #{query.subjectCode}


            AND l.business_type = #{query.businessType}


            AND l.business_id = #{query.businessId}



ORDER BY l.create_time DESC
